var ITEMS=[["What tile setters do","Tile setters install ceramic, porcelain, stone, and glass tile on floors, walls, showers, and backsplashes. Layout is the art; waterproofing is the science. Good setters are booked months out."], ["Essential tools","Wet saw, tile cutter (snap), trowels (various notches), spacers or leveling clips, grout float, sponges, buckets, level, chalk line, and knee pads. Pros add: large-format suction cups and a mixer."], ["Key skills","Layout: centering patterns and avoiding slivers. Thinset mixing and troweling. Cutting: wet saw curves and outlets. Waterproofing showers (the critical skill). Grouting cleanly. Caulking movement joints."], ["Safety essentials","Silica dust: wet cut or respirators. Knee protection \u2014 tile work destroys knees. Eye protection cutting. Back care lifting boxes. Electrical awareness around outlets being tiled."], ["Getting started","Start as a helper mixing thinset and carrying tile. Learn layout before speed. Shower waterproofing courses (Schluter etc.) build credentials. Photos of crisp grout lines are your portfolio."], ["Pro tips","Dry-lay the pattern first. Back-butter large tiles. Waterproofing is not optional in showers \u2014 flood-test it. Lippage systems for large format. Clean grout haze before it cures."], ["Thinset","Trade term \u2014 Thinset: The cement mortar bonding tile."], ["Notch trowel","Trade term \u2014 Notch trowel: Creates mortar ridges; size matches tile."], ["Back-buttering","Trade term \u2014 Back-buttering: Applying mortar to the tile back."], ["Lippage","Trade term \u2014 Lippage: Height difference between tile edges."], ["Grout","Trade term \u2014 Grout: The filler between tiles."], ["Sanded vs unsanded","Trade term \u2014 Sanded vs unsanded: Grout types by joint width."], ["Movement joint","Trade term \u2014 Movement joint: Flexible caulked gap for expansion."], ["Waterproof membrane","Trade term \u2014 Waterproof membrane: Shower waterproofing layer."], ["Flood test","Trade term \u2014 Flood test: Filling a shower pan to verify waterproofing."], ["Curb","Trade term \u2014 Curb: The shower threshold."], ["Niche","Trade term \u2014 Niche: The recessed shower shelf."], ["Deco strip","Trade term \u2014 Deco strip: Decorative accent tile band."], ["Bullnose","Trade term \u2014 Bullnose: Finished-edge tile."], ["Pencil trim","Trade term \u2014 Pencil trim: Narrow finishing trim."], ["Large format","Trade term \u2014 Large format: Big tiles needing special handling."], ["Substrate","Trade term \u2014 Substrate: The surface tile bonds to."], ["Uncoupling membrane","Trade term \u2014 Uncoupling membrane: Crack-isolation layer."], ["Efflorescence","Trade term \u2014 Efflorescence: Mineral deposits on tile/grout."], ["Sealer","Trade term \u2014 Sealer: Protective treatment for stone and grout."]];
function ask(n){var out=[],seen={};n=Math.min(n,ITEMS.length);for(var k=0;k<n;k++){var it=ITEMS[(Math.random()*ITEMS.length)|0];out.push("Q"+(k+1)+": "+it[0]+"\nA"+(k+1)+": "+it[1]);}return out.join("\n\n");}
function lookup(q){q=String(q).toLowerCase();var h=[];for(var i=0;i<ITEMS.length;i++){if((ITEMS[i][0]+" "+ITEMS[i][1]).toLowerCase().indexOf(q)>=0)h.push(ITEMS[i][0]+" — "+ITEMS[i][1]);}return h.length?h.join("\n"):"no match for "+q;}
